for m in [2,3,4]:
 n=2*m+1;a=F(1,2**m)
 vals=[1 if (x&1 and any(x>>i&1 for i in range(1,m+1)) and any(x>>i&1 for i in range(m+1,2*m+1))) else -1 for x in range(1<<n)]
 inf=[F(sum(vals[x]!=vals[x^(1<<i)] for x in range(1<<n)),1<<n) for i in range(n)]
